function buildPlaces() {
  const places = []; let counter = 1;
  Object.entries(RAW_ATTRACTIONS).forEach(([province, list]) => {
    list.forEach(a => {
      const defaults = CATEGORY_DEFAULTS[a.cat] || CATEGORY_DEFAULTS["فرهنگی"];
      places.push({
        id:`place-${String(counter++).padStart(4,"0")}`, name:a.name, province, locality:province,
        category:a.cat, type:a.type||a.cat, lat:a.lat, lng:a.lng, short:a.short||"",
        description:a.short||"", image:a.image||FALLBACK_IMAGE(a.name),
        difficulty:a.difficulty||defaults.difficulty, season:a.season||defaults.season,
        duration:a.duration||defaults.duration, status:"نمونه نمایشی",
        tags:a.tags||defaults.tags, visit:a.visit||"شرایط بازدید را پیش از سفر بررسی کنید.",
        alert:a.alert||"", verified:false, color:CATEGORY_COLORS[a.cat]||CATEGORY_COLORS["فرهنگی"]
      });
    });
  });
  return places;
}
